export function estimateContextTokens(value){const text=typeof value==='string'?value:JSON.stringify(value??null);return Math.ceil(Buffer.byteLength(text,'utf8')/3.5);}
export function decideContextRotation({estimatedTokens,contextWindow,softRatio=0.65,hardRatio=0.75,gateComplete=false,largeToolResult=false,constraintDrift=false}={}){if(!Number.isFinite(estimatedTokens)||estimatedTokens<0||!Number.isInteger(contextWindow)||contextWindow<1024)throw new Error('invalid context estimate');if(constraintDrift)return {decision:'ROTATE',reason:'CONSTRAINT_DRIFT',utilization:estimatedTokens/contextWindow};const utilization=estimatedTokens/contextWindow;if(utilization>=hardRatio)return {decision:'ROTATE',reason:'HARD_CONTEXT_THRESHOLD',utilization};if(gateComplete)return {decision:'ROTATE',reason:'BOUNDED_GATE_COMPLETE',utilization};if(largeToolResult&&utilization>=softRatio)return {decision:'ROTATE',reason:'LARGE_TOOL_RESULT_SOFT_THRESHOLD',utilization};if(utilization>=softRatio)return {decision:'CHECKPOINT',reason:'SOFT_CONTEXT_THRESHOLD',utilization};return {decision:'CONTINUE',reason:'CONTEXT_WITHIN_BUDGET',utilization};}
