export function buildFreshSessionPack({fixedContract,checkpoint,latestInstruction}={}){if(!fixedContract||!checkpoint||checkpoint.protocol!=='devexec.session-checkpoint')throw new Error('fresh session pack inputs invalid');return {protocol:'devexec.local-session-pack',schema_version:1,fixed_contract:fixedContract,session_checkpoint:checkpoint,latest_supervisor_instruction:latestInstruction||null};}
